    if (K === "K_QADAM" && !(Array.isArray(dd.qadamlar) && dd.qadamlar.filter(function(x){ return String(x||"").trim(); }).length)) X.push("k) " + n + ": K_QADAM uchun qadamlar yo'q");
    if (K === "K_KARTA" && !(dd.yanlis && dd.dogru)) X.push("k) " + n + ": K_KARTA uchun yanlis/dogru yo'q");
    // DZ-3.2c: "o'zgarmadi / değişmedi / aynı / sabit" → o'suvchi grafik taqiq
    if (TEKIS.test(low([s.sarlavha, s.matn, src.sarlavha, src.tana].join(" ")))) {
      if (K === "K_USTUN" && dv.length >= 2 && !tekis(dv)) X.push("l) " + n + ": 'değişmedi/aynı/sabit' — o'suvchi ustunlar taqiq: bir xil ustunlar yoki K_RAQAM");
      if (K === "K_KESISH" && la.length >= 2 && (!tekis(la) || !tekis(lb))) X.push("l) " + n + ": 'değişmedi/aynı/sabit' — o'suvchi chiziq taqiq: gorizontal chiziq yoki K_RAQAM");
      if (K === "K_TAQQOS" && Number(dd.a) !== Number(dd.b)) X.push("l) " + n + ": 'değişmedi/aynı/sabit' — farqli K_TAQQOS taqiq: K_RAQAM");
    }
    // DZ-3.3: iqtibos faqat manbada qo'shtirnoq ichida berilgan gap
