      if (!iq) X.push("k) " + n + ": K_IQTIBOS uchun iqtibos yo'q");
      else if (!tirnoq.some(function(q){ return q.indexOf(iq) >= 0 || (iq.indexOf(q) >= 0 && q.length >= iq.length * 0.8); })) X.push("m) " + n + ": K_IQTIBOS matni manbada qo'shtirnoq ichida yo'q — bu xulosa, A3_TEZIS sarlavhasi bo'lsin");
    }
