    if (K === "K_ORALIQ" && DAROMAD.test(low([s.raqam, s.sarlavha, faktEkran(s.s_id)] /* src emas: slayd tartibi siljishi mumkin */.join(" ")))) X.push("n) " + n + ": K_ORALIQ faqat ulush foizi uchun; daromad/farq foizi — K_RAQAM yoki K_TAQQOS");
