function tson(t){ t = String(t); if (/^\d{1,3}(\.\d{3})+$/.test(t)) return Number(t.replace(/\./g,"")); return Number(t.replace(",", ".")); }
function sonlar(t){ return (String(t||"").match(/\d+([.,]\d+)*/g) || []).map(tson); }
var RAQAM_RE = /[%€$₺£]?\s?\d+(?:[.,]\d+)*(?:\s*[–-]\s*%?\s?\d+(?:[.,]\d+)*)?%?/;
var DAROMAD = /y[ıi]ll[ıi]k|getiri|geride|gerisinde/;
